from collections import *

class LCP:
    def __init__(self, s: str):
        self.s = s
        self.n = len(s)
        self.info = self.tree(*zip(*(enumerate(s)), *reversed(zip(*(enumerate(s)), *reversed(range(self.n-1, 0, -1))))))

    def tree(self, it):
        left, right, root, candidate = 0, self.n, 0, -1
        while left <= right:
            mid = (left + right) >> 1
            if candidate < mid and self.num(it[0][0] + right - 1, it[1], candidate) < mid - candidate - 1:
                left = mid + 1
                candidate = mid
            else:
                right = mid - 1
            if candidate == mid - it[1][-1] - 1 and mid - it[1][-1] == it[0][-1]: candidate += 1
        return root

    def num(self, i, j, less_than):
        total, down, root = 0, False, self.info
        while 0 < j:
            a1, b1, a2, b2, used, prefix = i
            if j < a1: break
            if j > b1:
                total += prefix * (j + 1 - b1 - down)
                break

            index = j - a2
            if 0 <= index:
                prefix = (root[index][j][1] if index else (1, less_than))
                if root[index][j - index - 1][1] < less_than: prefix = (0, less_than)
                down &= not prefix[1] if prefix else root[index][j - index - 1][1]
                total += prefix[0] * ((root[index][j - index - 1][0] if prefix else 0) + 1)
            i = (root[index][j][0], j - index - 1, a1, b1, used | (b2 - a1), prefix)
        return total

