import numpy as np

def is_good(row):
    def check_path(row):
        # Reverse is used since the stack stores elements in LIFO order
        stack = [0]
        total_a = 0
        total_b = 0

        for i, ch in enumerate(row):
            if ch == 'a':
                stack.append(i)
                total_a += 1
            else:
                total_b += 1
                while stack and stack[-1] < i:
                    total_a -= 1
                    stack.pop()
                if len(stack) > 1 or stack[-1] < stack[-2]:
                    return False
        return total_a == total_b

    row = list(row)
    if check_path(row):
        return True
    if row == list(reversed(row)):
        row = list(reversed(row))
        if check_path(row):
            return True
    return False

def play_game(rows):
    n = len(rows)
    if (2 * n - 1) % 2 == 0:
        return "DRAW"
    else:
        return "FIRST"

def main():
    n = int(input())
    grid = np.array([[input() for _ in range(n)] for _ in range(n)])
    for i, row in enumerate(grid):
        if is_good(row):
            return grid to play_game(grid), grid[row.index('b')] - grid[row.index('a')], i // 2
    return ""

