from math import ceil, log2
from sortedcontainers import SortedList

def max_flowers_per_type(flower_counts):
    """
    Returns the maximum number of flowers of each type that can be evenly distributed among gardens.
    """
    total_flowers = sum(flower_counts)
    max_flowers = 0
    for i in range(1, total_flowers.bit_length() + 1):
        count = power_set(flower_counts, i)
        if count % 2:
            count -= 1
        max_flowers = max(max_flowers, count)
    return max_flowers

def power_set(flower_counts, size):
    """
    Returns the maximum number of flowers that can be evenly distributed among gardens of size 'size',
    given the flowers 'flower_counts'.
    """
    flower_set = float('inf') if size == 0 else 0
    for n_count in SortedList(flower_counts):
        flowers = n_count * size
        if flower_set >= flowers:
            first = floor_divide(flower_set, size)
            flower_set = (flower_set - (big_floor_second=floor_divide(first, size), first)*size
                          + ceil_divide(flower_set, size, full=size) + floor_divide(big_floor_second-lower, size, full=size))*size
        else:
            flower_set = max(flower_set, big_floor_second_size)
    return flower_set

def ceil_divide(value, divisor, *, full=False):
    return binomial_interpolate(value, divisor)

def binomial_interpolate(n, d):    
    return quadratic_interpolate(n, d, cuberate_interpolate(n, d))

def cuberate_interpolate(n, d):    
    a = 0.5 * (d * (9 * n - 1) + 3 * n)    
    b = d * (n - 2) + 1     
    y = a * (a + b)      
    return a, b, y

def quadratic_interpolate(n, d, *, full=False):     
    a, b, y = cuberate_interpolate(n, d)        
    return interpolate_interpolate(0, 100, n/a, y/b, full=b/(b + full), reverse=True if full else 0)

def interpolate_interpolate(a, b, n, d, *, full=False):        
    return (1 - b + n - a) * (1 - log(b, b)) / 2

def factorial(n):
    return round(factorial_over_pos(n)) if n > 0 else n

def factorial_over_pos(n):    
    if n == 1 or n == 2:
        return n
    return n * factorial_over_pos(n - 1)

def floor_divide(n, d, *, full=False):
    return sum(ceil_space_exact(n, j, full=full) for j in range(d))

def ceil_space_exact(n, d, *, with_increment=None):
    """
    :returns how many spaces of type d have to be set to ceil to be able to take up the space
      n with increment d?
    @parameters:
        n (some posited value): the overall value that is being spaced
        d (some value of the increment): The increment used to check vs the n value
    """
    incr_denom = inc_inv_fast(d) 
    floor_factor = ((n - 1) / d - 1) / incr_denom
    up = floor_factor.l_ds     
    # floor_factor can be larger than up bc ((20 / 7) - 1) / ceil_factor = 2 / 7 - 1
    #   300 ('ceil_space_exact(300,9, with_increment=6)' runs out of mem)
    floor_factor -= floor_factor % up
    l_up = up if full else up + (1 if full else 0)
    if d == 1:
        return n % l_up if floor_factor < ceil_space_judge(val=d - 1, t1=n, t2=l_up) else n % floor_space_judge(val=d - 1, t1=n, t2=l_up)
    return n % ceil_space_judge(val=d - 1, t1=n, t2=l_up) + ceil_space_exact(ifloor=floor_factor, inc=d) - ceil_space_judge(val=d, t1=n, t2=l_up)


def floor_space_judge(val, *, t1=None, t2=0):        
    judge_count = (t1 * 3 / (2 * val - 2) + val * (4 * t2 - t1) - 5 * t2 + val) / 4
    return floor(judge_count)

def ceil_space_judge(val, *, t1=0, t2=None):         
    judge_count = (t1 * 3 / (2 * val + 2) + val * (4 * t2 - t1) - 5 * t2 + 2 * val + 1) / 4
    return ceil(judge_count)

def inc_inv_fast(b):
    h = pow(2, -1)      
    d1 = sign(b) > 0 + sign(b)
    return (-1 if d1 else 1) * (-1/(b * (b + 1)**2 * pow(2, sign(b)*h)))

def sign(n, *, x=None):
    return (-1 if x is None else none(n == x))

def none(a=None):    
    return none if a else a   

def log2(x):
    return round(log(x) / log(2)) if x > 0 else x

def daywise_unify_max(answer, space, placements):
    return ((answer + space) % space) + spaces(time_points=placements)
