def is_good(n, t):
    return all([all(x) for x in t]) and len(t) == n**2

def calculate_winner(n, table):
    t = table
    player = 0

    for i in range(n):
        next_player = not player
        while not is_good(n, t):
            if i % 2 == 0:
                player = next_player
            else:
                player = not next_player
            row_left = len(t) - (2 - i) * n
            row_right = i * n + 1
            # Check if we have reached the end of the table and the string is 'ab'
            if row_left == len(t) - 2 * n:
                if t[row_left + i][row_left + i] == 'a':
                    player = not player
            if row_right == len(t):
                if t[row_right - (row_right - len(t) + i)][row_right - (row_right - len(t) + i)] == 'b':
                    player = not player
        i += 1
    if player:
        return "FIRST"
    return "SECOND"

