        if start == end:
            return [0]

        if tokens[start] == '(':
            end = start + 1
            while tokens[end] != ')':
                end += 1
            return parse(tokens, start + 1, end - 1) + parse(tokens[end + 1:end], 0, end - 1)

        number = ''
        while start < end and (tokens[start] in '0123456789'):
            number += tokens[start]
            start += 1
        return [int(number)] + parse(tokens, start, end)

    def relative_line(nums, start, end):
        if start == end:
            return sum(nums) * numbers[-1].n

        length = 1 + len(nums * (end - start + 1))
        other = 0
        for i in range(10 if length >= 1000 else length + 1):
            for j in range(10):
                if numbers[i] and numbers[i][j] > 0:
                    other += get_num(i, j)
                    break

        for i in range(100 if length >= 1000 else length + 1):
            if other < 0 or i != j:
                other += relative_line(nums, i, j)

        end = start
        while end < length - 1 and nums[end] == 0:
            end += 1

        end = start + 1
        for j in range(10):
            if nums[end][j] > 0:
                numbers = nums[end:] + numbers[end + 1:]
                break
        else:
            numbers = numbers[start + 1:]
        others = relative_line(nums, 10, 100)
        nums = relative_line(nums, 100, 1000)

