import sys

def min_operations_to_equal_elements(N, A):
    count_operations = 0
    while len(A) > 1:
        max_value = A[0] + A[1]
        for i in range(len(A)):
            if A[i] > max_value:
                max_value = A[i]
        count_operations += 1
        for i in range(len(A) - 1):
            if A[i] == max_value:
                A[i], A[i + 1] = A[i + 1], A[i]
                break
        del A[len(A) - 1]
    return count_operations

