import sys

def parse_expression(expression):
    stack = []

    for char in expression:
        if char in ["-", "+", "(", ")"]:
            if stack:
                term = int(stack.pop())
                if char == "(":
                    new_term = parse_term(stack.pop())
                    term *= len(new_term)
                else:
                    term += int(char)
            else:
                term = int(char)
        elif char.isdigit():
            stack.append(char)
        else:
            if stack:
                term = int(stack.pop())
                stack.append(str(term) + char)
            else:
                stack.append(str(char))

    return int("".join(stack))

def parse_term(stack):
    term = -int(stack.pop())

    if not stack:
        return term

    op = stack.pop()
    if op == "-":
        term *= -1
    if op == "+":
        return 0

    while stack and stack[-1] in ["(", "-"]:
        next_term = parse_term(stack.pop())
        if stack[-1] == "-":
            term -= next_term
        else:
            term <<= 1
            term += next_term

    return term

