def decode(expression):
    def eval_number(number):
        return int(number, 36) % mod

    parts = expression.split('(')
    result = 1
    term = 0
    for i, part in enumerate(parts):
        if part.startswith('(') and part.endswith(')'):
            result = result * eval_number(part[1:-1]) % mod
        else:
            numbers = [i if x in '123456789' else x for x in part] + ['0']
            pos = numbers.index('0')
            for digit in numbers[::-1][pos:]:
                term *= 10
                term += eval_number(digit)
            result = term * eval_number(parts[i-1]) % mod
            term = 0

    return eval_number(result)

