from collections import Counter
from typing import List

def is_satisfiable(clauses: List[List[int]], m: int) -> bool:
    variables_count = Counter()
    for clause in clauses:
        literals = []
        for i in clause:
            if i > 0:
                literals.append(i)
            else:
                literals.append(-i)
        negated_literals = list(set(literals))
        variables_count.update(negated_literals)

    print("Variables count:", variables_count)
    negated_count = sum(1 for var in variables_count if var < 0)
    total_count = len(clauses)

    return negated_count <= total_count // 2

def find_satisfying_assignment(clauses: List[List[int]], m: int) -> List[int]:
    variables = list(range(m))

    def dfs(v, assignment): # stack depth first search
        visit = [False] * m

        if v >= m:
            return assignment

        for i in range(v, m):
            if not visit[i]:
                count = 0
                for j in range(len(clauses[i])):
                    if j < m and clauses[i][j] >= 0:
                        visit[j] = True
                    elif clauses[i][j] < 0:
                        count += 1
                        if count > 1:
                            break

                if count >= 2:
                    continue

                if count == 0:
                    if dfs(i + 1, assignment):
                        return assignment

    return dfs(0, [0] * m) 

