            s[x - 1] = new[:res]
        k = bisect_left(lcp_array, x - counter[s[x - 1]], key=lambda x: x and x[0])
        if k == len(lcp_array):
            max_s = sorted(s, reverse=True)
            max_s[lcp_array[k] + x - len(s) + 1 - max_lcp] = new[:]
            n += 1
        else:
            insort(max_lcp, lcp_array[k] + x - len(s) + 1, key=lambda x: x and x[0])
        ans += k - bisect_left(lcp_array, n - x + 1) + q
        q -= 1
    print(ans)
