from itertools import count
from math import pow

def solve(pre_exp, i):
    previous_prefix, prefix = '', ''
    base = 10**9 + 7

    # Break down the prefix function computation into steps for readability
    for index_prefix, index_in_exp in count(0, 1):
        if index_in_exp == len(pre_exp):
            return previous_prefix
        if index_prefix >= len(prefix):
            if index_in_exp == 0:
                break
            s = prefix[:index_in_exp-1]
            index_base = index_prefix // len(s) + 1
            previous_prefix = long(s) * base ** index_base + previous_prefix
            break

        s, index_in_exp, index_prefix = pre_exp[index_prefix:index_in_exp], index_in_exp - index_prefix, len(prefix)

    return solve(pre_exp, i + 1)\
        - previous_prefix + base * (prefix != '' or 1) + prefix != '' + prefix

