def arrange_bags(n, s, a):
    if s % n != 0:
        return -1

    remainder = s // n
    bags = [[] for _ in range(n)]

    for i in range(n):
        coins = a[i]
        current_bags = []

        while coins > 0 and i < n:
            if i < len(bags):
                current_bags.append(i)
                coins -= bags[i]
            else:
                i -= 1
                if i >= 0 and i < n:
                    bags[i].append(1)
                    coins -= 1
                else:
                    return -1

        if coins > 0:
            return -1

    for i in range(n):
        current_bags = bags[i]
        if len(current_bags) > 1:
            for j in range(1, len(current_bags)):
                bags[current_bags[j - 1]].append(current_bags[j])

    if remainder > 0:
        for i in range(n):
            bags[i].append(remainder)

    return "\n".join(str(len(bag)) + " " + " ".join(str(bag) for bag in bags[i]) for i in range(n))

# Example usage
print(arrange_bags(3, 3, [1, 3, 1]))
