def count_common_numbers(parent, value):
    global tree
    visited = [False] * (len(tree) + 1)
    return _count_common_numbers(parent, value, visited)

def _count_common_numbers(parent, value, visited):
    if visited[value]:
        return 0
    else:
        visited[value] = True
        for neighbor in tree[value]:
            if neighbor == parent:
                continue
            ans = _count_common_numbers(value, neighbor)
            if min(ans, count_common_numbers(value, neighbor)) != 0:
                return max(ans, count_common_numbers(value, neighbor)) + 1
        return 0

