import sys
from collections import defaultdict

def bfs(tree, start_node):
    visited = {node: False for node in range(1, len(tree) + 1)}
    queue = [start_node]

    while queue:
        node = queue.pop(0)
        visited[node] = True
        for neighbor in tree[node]:
            if not visited[neighbor]:
                queue.append(neighbor)

    return visited

def check_tree(tree, root):
    visited = bfs(tree, root)

    if not all(visited[node] for node in range(1, len(tree) + 1)):
        return -1

    for node in range(1, len(tree) + 1):
        if visited[node] and len(tree[node]) != visited[node] * 2:
            return -1

    return root

